package com.nivor.journal;
import com.nivor.common.exception.ResourceNotFoundException;import com.nivor.journal.dto.JournalRequest;import com.nivor.user.*;import java.time.LocalDate;import java.util.List;import org.jsoup.Jsoup;import org.jsoup.safety.Safelist;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class JournalService{
private final JournalEntryRepository entries;private final UserService users;public JournalService(JournalEntryRepository e,UserService u){entries=e;users=u;}
@Transactional(readOnly=true)public List<JournalEntry> list(String email,LocalDate date,LocalDate from,LocalDate to){Long uid=users.getByEmail(email).getId();if(date!=null&&(from!=null||to!=null))throw new IllegalArgumentException("Use either date or a date range");if((from==null)!=(to==null))throw new IllegalArgumentException("Both from and to are required");if(from!=null){if(to.isBefore(from))throw new IllegalArgumentException("to must not be before from");return entries.findAllByUser_IdAndEntryDateBetweenOrderByEntryDateDesc(uid,from,to);}return date==null?entries.findAllByUser_IdOrderByEntryDateDesc(uid):entries.findAllByUser_IdAndEntryDate(uid,date);}
@Transactional(readOnly=true)public JournalEntry get(String email,Long id){return owned(email,id);}@Transactional public JournalEntry create(String email,JournalRequest r){JournalEntry e=new JournalEntry();e.setUser(users.getByEmail(email));apply(e,r);return entries.save(e);}@Transactional public JournalEntry update(String email,Long id,JournalRequest r){JournalEntry e=owned(email,id);apply(e,r);return e;}@Transactional public void delete(String email,Long id){entries.delete(owned(email,id));}
private JournalEntry owned(String email,Long id){return entries.findByIdAndUser_Id(id,users.getByEmail(email).getId()).orElseThrow(()->new ResourceNotFoundException("Journal entry not found"));}private void apply(JournalEntry e,JournalRequest r){e.setTitle(r.title()==null?null:r.title().trim());e.setContent(Jsoup.clean(r.content(),Safelist.basic()));e.setMood(r.mood());e.setTags(r.tags());e.setEntryDate(r.entryDate());}
}
